function createUser(input: { email: string; name: string }, existingEmails: string[]) {
  const userErrors: { field: string; message: string }[] = [];
  const email = input.email.toLowerCase();
  if (!email.includes('@')) userErrors.push({ field: 'email', message: 'Email is invalid' });
  if (existingEmails.some((e) => e.toLowerCase() === email)) userErrors.push({ field: 'email', message: 'Email is taken' });
  if (!input.name.trim()) userErrors.push({ field: 'name', message: 'Name is required' });
  if (userErrors.length) return { user: null, userErrors };
  return { user: { email, name: input.name }, userErrors };
}

