function queryCost(selection: Record<string, any>): number {
  let cost = 0;
  for (const [key, value] of Object.entries(selection)) {
    if (key === '__args') continue;
    if (value === true) { cost += 1; continue; }
    const multiplier = value.__args?.first ?? 1;
    cost += 1 + multiplier * queryCost(value);
  }
  return cost;
}

