function executeFields(fields: { name: string; nonNull: boolean; value?: unknown; error?: string }[]) {
  const data: Record<string, unknown> = {};
  const errors: { message: string; path: string[] }[] = [];
  let nullParent = false;
  for (const f of fields) {
    if (f.error) {
      errors.push({ message: f.error, path: [f.name] });
      if (f.nonNull) nullParent = true;
      data[f.name] = null;
    } else data[f.name] = f.value;
  }
  return { data: nullParent ? null : data, errors };
}

