function depthWithFragments(selection: Record<string, any>, fragments: Record<string, Record<string, any>>): number {
  let depth = 0;
  for (const [key, value] of Object.entries(selection)) {
    let d: number;
    if (key.startsWith('...')) d = depthWithFragments(fragments[key.slice(3)] ?? {}, fragments);
    else d = value === true ? 1 : 1 + depthWithFragments(value, fragments);
    depth = Math.max(depth, d);
  }
  return depth;
}

