function pageAfter(items: { id: number; createdAt: number }[], first: number, after: string | null): number[] {
  let rest = items;
  if (after) {
    const [ts, id] = after.split('|').map(Number);
    rest = items.filter((p) => p.createdAt < ts || (p.createdAt === ts && p.id < id));
  }
  return rest.slice(0, first).map((p) => p.id);
}

